import{_ as l,a0 as p,w as r,s as o,ao as d,I as n,x as a,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"在 LXD 2.3 及以上版本中管理网络 | LCTT x X-CMD","titleTemplate":false,"description":"在 LXD 2.3 及以上版本中管理网络 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 LXD 2.3 及以上版本中管理网络 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 LXD 2.3 及以上版本中管理网络 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20161027 Network management with LXD","title":"在 LXD 2.3 及以上版本中管理网络","tag":"201706","desc":""},"relativePath":"201706/20161027 Network management with LXD.md","filePath":"[post].md"}'),h={name:"201706/20161027 Network management with LXD.md"};function c(g,s,u,k,b,f){const e=p("Link");return r(),o("div",null,[s[25]||(s[25]=d(`<h1 id="在-lxd-2-3-及以上版本中管理网络" tabindex="-1">在 LXD 2.3 及以上版本中管理网络 <a class="header-anchor" href="#在-lxd-2-3-及以上版本中管理网络" aria-label="Permalink to “在 LXD 2.3 及以上版本中管理网络”">​</a></h1><p><img src="https://linuxcontainers.org/static/img/containers.png" alt="LXD logo"></p><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p>当 LXD 2.0 随着 Ubuntu 16.04 一起发布时，LXD 联网就简单了。要么你可以使用 <code>lxd init</code> 来配置，为你的容器自己提供一个 “lxdbr0” 网桥，要么使用一个已存在的物理接口。</p><p>虽然这确实有效，但是有点混乱，因为大部分的桥接配置发生在 Ubuntu 打包的 LXD 之外。那些脚本只能支持一个桥接，并且没有通过 API 暴露，这使得远程配置有点痛苦。</p><p>直到 LXD 2.3，LXD 终于发展了自己的网络管理 API ，并有相应的命令行工具。这篇文章试图来简述这些新的功能。</p><h3 id="基础联网" tabindex="-1">基础联网 <a class="header-anchor" href="#基础联网" aria-label="Permalink to “基础联网”">​</a></h3><p>在初始情况下，LXD 2.3 没有定义任何网络。<code>lxd init</code> 会为你设置一个，并且默认情况下将所有新的容器连接到它，但是让我们亲手尝试看下究竟发生了些什么。</p><p>要创建一个新的带有随机 IPv4 和 IP6 子网，并启用 NAT 的网络，只需要运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network create testbr0</span></span>
<span class="line"><span>Network testbr0 created</span></span></code></pre></div><p>你可以如下查看它的配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network show testbr0</span></span>
<span class="line"><span>name: testbr0</span></span>
<span class="line"><span>config:</span></span>
<span class="line"><span> ipv4.address: 10.150.19.1/24</span></span>
<span class="line"><span> ipv4.nat: &quot;true&quot;</span></span>
<span class="line"><span> ipv6.address: fd42:474b:622d:259d::1/64</span></span>
<span class="line"><span> ipv6.nat: &quot;true&quot;</span></span>
<span class="line"><span>managed: true</span></span>
<span class="line"><span>type: bridge</span></span>
<span class="line"><span>usedby: []</span></span></code></pre></div><p>如果你不想要那些自动配置的子网，你可以这么做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network create testbr0 ipv6.address=none ipv4.address=10.0.3.1/24 ipv4.nat=true</span></span>
<span class="line"><span>Network testbr0 created</span></span></code></pre></div><p>那就会这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network show testbr0</span></span>
<span class="line"><span>name: testbr0</span></span>
<span class="line"><span>config:</span></span>
<span class="line"><span> ipv4.address: 10.0.3.1/24</span></span>
<span class="line"><span> ipv4.nat: &quot;true&quot;</span></span>
<span class="line"><span> ipv6.address: none</span></span>
<span class="line"><span>managed: true</span></span>
<span class="line"><span>type: bridge</span></span>
<span class="line"><span>usedby: []</span></span></code></pre></div><p>如果你的容器没有使用它，那么创建的网络对你也没什么用。要将你新创建的网络连接到所有容器，你可以这么做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network attach-profile testbr0 default eth0</span></span></code></pre></div><p>要将一个网络连接到一个已存在的容器中，你可以这么做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network attach my-container default eth0</span></span></code></pre></div><p>现在，假设你已经在机器中安装了 openvswitch，并且要将这个网桥转换成 OVS 网桥，只需更改为正确的驱动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network set testbr0 bridge.driver openvswitch</span></span></code></pre></div><p>如果你想要一次性做一系列修改。<code>lxc network edit</code> 可以让你在编辑器中交互编辑网络配置。</p><h3 id="静态租约及端口安全" tabindex="-1">静态租约及端口安全 <a class="header-anchor" href="#静态租约及端口安全" aria-label="Permalink to “静态租约及端口安全”">​</a></h3><p>使用 LXD 管理 DHCP 服务器的一个好处是可以使得管理 DHCP 租约很简单。你所需要的是一个容器特定的网卡设备以及正确的属性设置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@yak:~# lxc init ubuntu:16.04 c1</span></span>
<span class="line"><span>Creating c1</span></span>
<span class="line"><span>root@yak:~# lxc network attach testbr0 c1 eth0</span></span>
<span class="line"><span>root@yak:~# lxc config device set c1 eth0 ipv4.address 10.0.3.123</span></span>
<span class="line"><span>root@yak:~# lxc start c1</span></span>
<span class="line"><span>root@yak:~# lxc list c1</span></span>
<span class="line"><span>+------+---------+-------------------+------+------------+-----------+</span></span>
<span class="line"><span>| NAME |  STATE  |        IPV4       | IPV6 |    TYPE    | SNAPSHOTS |</span></span>
<span class="line"><span>+------+---------+-------------------+------+------------+-----------+</span></span>
<span class="line"><span>|  c1  | RUNNING | 10.0.3.123 (eth0) |      | PERSISTENT | 0         |</span></span>
<span class="line"><span>+------+---------+-------------------+------+------------+-----------+</span></span></code></pre></div><p>IPv6 也是相同的方法，但是换成 <code>ipv6.address</code> 属性。</p><p>相似地，如果你想要阻止你的容器更改它的 MAC 地址或者为其他 MAC 地址转发流量（比如嵌套），你可以用下面的命令启用端口安全：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@yak:~# lxc config device set c1 eth0 security.mac_filtering true</span></span></code></pre></div><h3 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to “DNS”">​</a></h3><p>LXD 在网桥上运行 DNS 服务器。除了设置网桥的 DNS 域（ <code>dns.domain</code> 网络属性）之外，还支持 3 种不同的操作模式（<code>dns.mode</code>）：</p><ul><li><code>managed</code> ：每个容器都会有一条 DNS 记录，匹配它的名字以及已知的 IP 地址。容器无法通过 DHCP 改变这条记录。</li><li><code>dynamic</code> ：允许容器通过 DHCP 在 DNS 中自行注册。因此，在 DHCP 协商期间容器发送的任何主机名最终都出现在 DNS 中。</li><li><code>none</code> ： 针对那些没有任何本地 DNS 记录的递归 DNS 服务器。</li></ul><p>默认的模式是 <code>managed</code>，并且典型的是最安全以及最方便的，因为它为容器提供了 DNS 记录，但是不允许它们通过 DHCP 发送虚假主机名嗅探其他的记录。</p><h3 id="使用隧道" tabindex="-1">使用隧道 <a class="header-anchor" href="#使用隧道" aria-label="Permalink to “使用隧道”">​</a></h3><p>除了这些，LXD 还支持使用 GRE 或者 VXLAN 隧道连接到其他主机。</p><p>LXD 网络可以连接任何数量的隧道，从而轻松地创建跨多个主机的网络。这对于开发、测试和演示非常有用，生产环境通常更喜欢使用 VLAN 进行分割。</p><p>所以说，你想在主机 “edfu” 上有一个运行 IPv4 和 IPv6 的基础 “testbr0” 网络，并希望在主机 “djanet” 上使用它来生成容器。最简单的方法是使用组播 VXLAN 隧道。这种类型的隧道仅在两个主机位于同一物理段上时才起作用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@edfu:~# lxc network create testbr0 tunnel.lan.protocol=vxlan</span></span>
<span class="line"><span>Network testbr0 created</span></span>
<span class="line"><span>root@edfu:~# lxc network attach-profile testbr0 default eth0</span></span></code></pre></div><p>它在主机 “edfu” 上定义了一个 “testbr0” 桥接，并为其他主机能加入它设置了一个组播 VXLAN。在这个设置中，“edfu” 为这个网络扮演了一个路由器角色，提供 DHCP、DNS 等等，其他主机只是通过隧道转发流量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@djanet:~# lxc network create testbr0 ipv4.address=none ipv6.address=none tunnel.lan.protocol=vxlan</span></span>
<span class="line"><span>Network testbr0 created</span></span>
<span class="line"><span>root@djanet:~# lxc network attach-profile testbr0 default eth0</span></span></code></pre></div><p>现在你可以在任何一台主机上启动容器，并看到它们从同一个地址池中获取 IP，通过隧道直接互相通讯。</p><p>如先前所述，这个使用了组播，它通常在跨越路由器时无法很好工作。在这些情况下，你可以用单播模式使用 VXLAN 或者 GRE 隧道。</p><p>要使用 GRE 加入另一台主机，首先配置服务主机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@edfu:~# lxc network set testbr0 tunnel.nuturo.protocol gre</span></span>
<span class="line"><span>root@edfu:~# lxc network set testbr0 tunnel.nuturo.local 172.17.16.2</span></span>
<span class="line"><span>root@edfu:~# lxc network set testbr0 tunnel.nuturo.remote 172.17.16.9</span></span></code></pre></div><p>接着是“客户端”主机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@nuturo:~# lxc network create testbr0 ipv4.address=none ipv6.address=none tunnel.edfu.protocol=gre tunnel.edfu.local=172.17.16.9 tunnel.edfu.remote=172.17.16.2</span></span>
<span class="line"><span>Network testbr0 created</span></span>
<span class="line"><span>root@nuturo:~# lxc network attach-profile testbr0 default eth0</span></span></code></pre></div><p>如果你像使用 VXLAN，只要这么做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@edfu:~# lxc network set testbr0 tunnel.edfu.id 10</span></span>
<span class="line"><span>root@edfu:~# lxc network set testbr0 tunnel.edfu.protocol vxlan</span></span></code></pre></div><p>还有：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@nuturo:~# lxc network set testbr0 tunnel.edfu.id 10</span></span>
<span class="line"><span>root@nuturo:~# lxc network set testbr0 tunnel.edfu.protocol vxlan</span></span></code></pre></div><p>这里需要隧道 id 以防与已经配置的多播 VXLAN 隧道冲突。</p><p>这就是如何使用最近的 LXD 简化跨主机联网了！</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>LXD 使得从简单的单主机网络到数千个容器的非常复杂的跨主机网络的定义变得更加容易。它也使为一些容器定义一个新网络或者给容器添加第二个设备，并连接到隔离的私有网络变得很简单。</p>`,54)),n("p",null,[s[1]||(s[1]=a("虽然这篇文章介绍了支持的大部分功能，但仍有一些可以微调 LXD 网络体验的窍门。可以在这里找到完整的列表：",-1)),t(e,{href:"https://github.com/lxc/lxd/blob/master/doc/configuration.md#network-configuration"},{default:i(()=>[...s[0]||(s[0]=[a("https://github.com/lxc/lxd/blob/master/doc/configuration.md",-1)])]),_:1}),s[2]||(s[2]=a(" 。",-1))]),s[26]||(s[26]=n("h3",{id:"额外信息",tabindex:"-1"},[a("额外信息 "),n("a",{class:"header-anchor",href:"#额外信息","aria-label":"Permalink to “额外信息”"},"​")],-1)),n("ul",null,[n("li",null,[s[4]||(s[4]=a("LXD 主站：",-1)),t(e,{href:"https://linuxcontainers.org/lxd"},{default:i(()=>[...s[3]||(s[3]=[a("https://linuxcontainers.org/lxd",-1)])]),_:1})]),n("li",null,[s[6]||(s[6]=a("Github 地址： ",-1)),t(e,{href:"https://github.com/lxc/lxd"},{default:i(()=>[...s[5]||(s[5]=[a("https://github.com/lxc/lxd",-1)])]),_:1})]),n("li",null,[s[8]||(s[8]=a("邮件列表支持：",-1)),t(e,{href:"https://lists.linuxcontainers.org/"},{default:i(()=>[...s[7]||(s[7]=[a("https://lists.linuxcontainers.org",-1)])]),_:1})]),s[11]||(s[11]=n("li",null,"IRC 频道：#lxcontainers on irc.freenode.net",-1)),n("li",null,[s[10]||(s[10]=a("在线尝试 LXD：",-1)),t(e,{href:"https://linuxcontainers.org/lxd/try-it"},{default:i(()=>[...s[9]||(s[9]=[a("https://linuxcontainers.org/lxd/try-it",-1)])]),_:1})])]),s[27]||(s[27]=n("hr",null,null,-1)),n("p",null,[s[13]||(s[13]=a("via: ",-1)),t(e,{href:"https://www.stgraber.org/2016/10/27/network-management-with-lxd-2-3/"},{default:i(()=>[...s[12]||(s[12]=[a("https://www.stgraber.org/2016/10/27/network-management-with-lxd-2-3/",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=a("作者：",-1)),t(e,{href:"https://www.stgraber.org/author/stgraber/"},{default:i(()=>[...s[14]||(s[14]=[a("Stéphane Graber",-1)])]),_:1}),s[18]||(s[18]=a(" 译者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[15]||(s[15]=[a("geekpi",-1)])]),_:1}),s[19]||(s[19]=a(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[16]||(s[16]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[21]||(s[21]=[a("Linux中国",-1)])]),_:1}),s[24]||(s[24]=a(" 荣誉推出",-1))])])}const y=l(h,[["render",c]]);export{v as __pageData,y as default};
